import{_ as o,o as t,c as i,a5 as c}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Kế hoạch kỹ thuật System Health MongoDB","description":"","frontmatter":{},"headers":[],"relativePath":"feature/system-health-mongodb-refactor/plan.md","filePath":"feature/system-health-mongodb-refactor/plan.md"}'),n={name:"feature/system-health-mongodb-refactor/plan.md"};function d(r,e,l,a,s,h){return t(),i("div",null,[...e[0]||(e[0]=[c('<h1 id="ke-hoach-ky-thuat-system-health-mongodb" tabindex="-1">Kế hoạch kỹ thuật System Health MongoDB <a class="header-anchor" href="#ke-hoach-ky-thuat-system-health-mongodb" aria-label="Permalink to &quot;Kế hoạch kỹ thuật System Health MongoDB&quot;">​</a></h1><p>Tham chiếu gốc: <a href="./../../../../tuan-research/system-health-mongodb-refactor/plan.html">tuan-research/system-health-mongodb-refactor/plan.md</a>.</p><h2 id="_1-can-cu-code-va-điem-de-bo-sot" tabindex="-1">1. Căn cứ code và điểm dễ bỏ sót <a class="header-anchor" href="#_1-can-cu-code-va-điem-de-bo-sot" aria-label="Permalink to &quot;1. Căn cứ code và điểm dễ bỏ sót&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nguồn</th><th>Quan sát và hệ quả</th></tr></thead><tbody><tr><td>brandhub-infrastructure/docs/database/init-postgres-v2.sql:1112–1230</td><td>5 bảng, CHECK/FK, latest-only; chuyển Mongo phải thay bảo đảm đang do SQL thực hiện</td></tr><tr><td>brandhub-business-service/.../service/monitoring/HealthIngestionService.java</td><td>JPA lock target, kiểm tra collector, duplicate, ordering; không chỉ đổi annotation</td></tr><tr><td>brandhub-business-service/.../service/monitoring/ServerMonitoringService.java</td><td>Heartbeat dirty-check qua JPA; Mongo cần update tường minh, không replace document</td></tr><tr><td>brandhub-business-service/.../service/monitoring/MonitoringEnrollmentService.java</td><td>JdbcTemplate DELETE RETURNING + INSERT host cùng transaction</td></tr><tr><td>brandhub-business-service/.../service/monitoring/HealthQueryService.java</td><td>Page catalog trước, batch samples/collectors, status filter sau pagination</td></tr><tr><td>brandhub-business-service/.../service/monitoring/MonitoringHealthView.java</td><td>Tính freshness tại thời điểm đọc, không lưu status</td></tr><tr><td>brandhub-business-service/.../service/monitoring/MonitoringAccess.java</td><td>Current ADMIN đọc PostgreSQL; token hash so sánh constant-time</td></tr><tr><td>brandhub-monitoring/src/provision.mjs</td><td>Ghi SQL trực tiếp cả catalog trong một transaction; phải đổi cùng backend</td></tr><tr><td>brandhub-monitoring/src/main.mjs</td><td>Worker runtime gửi HTTP; không cần quyền ghi database catalog</td></tr><tr><td>brandhub-business-service/pom.xml, src/main/resources/application.yml</td><td>Đã có Spring Data MongoDB; cấu hình Mongo hiện hữu</td></tr></tbody></table><h2 id="_2-model-va-collections-mongodb" tabindex="-1">2. Model và Collections MongoDB <a class="header-anchor" href="#_2-model-va-collections-mongodb" aria-label="Permalink to &quot;2. Model và Collections MongoDB&quot;">​</a></h2><p>Dùng 4 collection thông thường trong database Mongo Business:</p><ol><li><p><code>monitoring_servers</code>:</p><ul><li><code>_id</code>: String (canonical UUID lowercase)</li><li><code>name</code>: String</li><li><code>ipAddress</code>: String (chuẩn hóa IPv4/IPv6)</li><li><code>environment</code>: String</li><li><code>deployedServices</code>: Array&lt;String&gt;</li><li><code>agentTokenHash</code>: String</li><li><code>cpuPercent</code>: Decimal128 / Double</li><li><code>ramPercent</code>: Decimal128 / Double</li><li><code>diskPercent</code>: Decimal128 / Double</li><li><code>uptimeSeconds</code>: Long (Int64)</li><li><code>lastSeenAt</code>: Date</li><li><code>createdAt</code>: Date</li><li><code>updatedAt</code>: Date</li></ul></li><li><p><code>monitoring_collectors</code>:</p><ul><li><code>_id</code>: String (UUID)</li><li><code>name</code>: String</li><li><code>serverId</code>: String (UUID)</li><li><code>tokenHash</code>: String</li><li><code>lastSeenAt</code>: Date</li><li><code>createdAt</code>: Date</li><li><code>updatedAt</code>: Date</li></ul></li><li><p><code>monitoring_health_targets</code>:</p><ul><li><code>_id</code>: String (UUID)</li><li><code>name</code>: String</li><li><code>kind</code>: String (SERVICE, CONTAINER, DATABASE, ENDPOINT)</li><li><code>environment</code>: String</li><li><code>serverId</code>: String (UUID)</li><li><code>serviceName</code>: String</li><li><code>instanceId</code>: String</li><li><code>collectorId</code>: String (UUID)</li><li><code>checkScope</code>: String</li><li><code>probeType</code>: String (HTTP, DOCKER, POSTGRESQL, REDIS, MONGODB, NEO4J)</li><li><code>probeConfig</code>: Object</li><li><code>assertion</code>: Object</li><li><code>credentialRef</code>: String</li><li><code>intervalSeconds</code>: Integer</li><li><code>timeoutSeconds</code>: Integer</li><li><code>staleAfterSeconds</code>: Integer</li><li><code>catalogVersion</code>: Long</li><li><code>createdAt</code>: Date</li><li><code>updatedAt</code>: Date</li><li><code>latestResult</code>: Object null hoặc chứa mẫu mới nhất: <ul><li><code>checkId</code>: String (UUID)</li><li><code>collectorId</code>: String (UUID)</li><li><code>outcome</code>: String (PASS, FAIL, ERROR)</li><li><code>checkedAt</code>: Date</li><li><code>checkedAtMicros</code>: Long</li><li><code>receivedAt</code>: Date</li><li><code>latencyMs</code>: Decimal128</li><li><code>reasonCode</code>: String</li><li><code>httpStatus</code>: Integer</li><li><code>runtimeState</code>: String</li><li><code>runtimeHealth</code>: String</li></ul></li></ul></li><li><p><code>monitoring_enrollments</code>:</p><ul><li><code>_id</code>: String (tokenHash hex 64)</li><li><code>name</code>: String</li><li><code>environment</code>: String</li><li><code>expiresAt</code>: Date (TTL index: <code>expireAfterSeconds: 0</code>)</li></ul></li></ol><h2 id="_3-persistence-seam-storage-mode" tabindex="-1">3. Persistence Seam &amp; Storage Mode <a class="header-anchor" href="#_3-persistence-seam-storage-mode" aria-label="Permalink to &quot;3. Persistence Seam &amp; Storage Mode&quot;">​</a></h2><ul><li>Thiết kế persistence seam qua interface <code>MonitoringStore</code> (hoặc các interfaces chuyên trách: <code>ServerMonitoringStore</code>, <code>HealthMonitoringStore</code>, <code>EnrollmentMonitoringStore</code>).</li><li>Implement hai adapter: <ol><li><code>PostgreSqlMonitoringStore</code>: giữ nguyên hành vi JDBC/JPA hiện tại cho fallback/rollback window.</li><li><code>MongoMonitoringStore</code>: sử dụng <code>MongoTemplate</code> cho conditional atomic updates (<code>$set</code>, <code>$unset</code>), transaction cho register, TTL và query projection.</li></ol></li><li>Cấu hình qua thuộc tính <code>monitoring.storage</code>: <code>postgres</code> (mặc định) hoặc <code>mongo</code>.</li><li>Services (<code>ServerMonitoringService</code>, <code>HealthIngestionService</code>, <code>HealthQueryService</code>, <code>MonitoringEnrollmentService</code>) phụ thuộc vào Seam, không trực tiếp thao tác JPA/Jdbc/Mongo.</li></ul><h2 id="_4-concurrency-va-transaction-rules" tabindex="-1">4. Concurrency và Transaction Rules <a class="header-anchor" href="#_4-concurrency-va-transaction-rules" aria-label="Permalink to &quot;4. Concurrency và Transaction Rules&quot;">​</a></h2><ul><li><strong>Heartbeat host/collector</strong>: Conditional <code>$set</code> với <code>_id</code> và <code>tokenHash</code> trong query selector; không dùng upsert, không dùng read-then-save để tránh overwrite metadata/credentials.</li><li><strong>Probe Result Ingestion</strong>: <ul><li>CAS update trên target: match <code>_id</code>, <code>collectorId</code>, <code>catalogVersion</code>, và điều kiện <code>latestResult</code> null HOẶC <code>latestResult.checkedAt</code> &lt; request.checkedAt.</li><li>Phân loại lỗi chính xác: duplicate checkId -&gt; return { duplicate: true }; older timestamp -&gt; 409 CONFLICT; collector mismatch -&gt; 403 FORBIDDEN; not found -&gt; 404 NOT_FOUND.</li></ul></li><li><strong>Enrollment</strong>: <ul><li><code>invite</code>: insert enrollment document với <code>_id=tokenHash</code>, TTL index trên <code>expiresAt</code>.</li><li><code>register</code>: Mongo session transaction: <code>findOneAndDelete</code> enrollment còn hạn (<code>expiresAt &gt; now</code>), <code>insert</code> server host. Nếu insert server lỗi, transaction tự rollback cả hai.</li></ul></li></ul>',11)])])}const m=o(n,[["render",d]]);export{u as __pageData,m as default};
